export type WorkerMountMode = 'ro' | 'rw'

export type WorkerResourceMount = {
  source: string
  destination: string
  mode: WorkerMountMode
}

export type WorkerResourceProfile = {
  cpus: number
  memoryMib: number
  pidsLimit: number
  network: WorkerNetworkMode
